// Autogenerated documentation for non-libc libraries: resolve a `-l` flag
// to its .pc file, scan its include dirs for C prototypes, and pull one-line
// summaries from man pages (lazily, cached). Best-effort by design: headers
// are not a database, so macros, multiline edge cases, and undocumented
// functions degrade gracefully instead of erroring.
import { execFileSync } from "child_process";
import * as fs from "fs";
import * as path from "path";

export interface HeaderFunction {
    name: string;
    header: string;
    signature: string;
    summary: string;
    lib: string;
}

function execQuiet(file: string, args: string[], timeoutMs = 15000): string | null {
    try {
        return execFileSync(file, args, {
            encoding: "utf8",
            timeout: timeoutMs,
            stdio: ["ignore", "pipe", "ignore"],
        });
    } catch {
        return null;
    }
}

/**	name<TAB>path lines of `pkg-config --list-all`, or scan pc dirs directly. */
export function pcFiles(): string[] {
    const out: string[] = [];
    const pcPath = execQuiet("pkg-config", ["--variable=pc_path", "pkg-config"]);
    const dirs = pcPath ? pcPath.trim().split(":") : ["/usr/lib/pkgconfig", "/usr/share/pkgconfig"];
    for (const dir of dirs) {
        let entries: string[];
        try {
            entries = fs.readdirSync(dir);
        } catch {
            continue;
        }
        for (const name of entries) {
            if (name.endsWith(".pc")) {
                out.push(path.join(dir, name));
            }
        }
    }
    return out;
}

function parseLibsLine(text: string): string[] {
    const libs: string[] = [];
    for (const line of text.split("\n")) {
        const m = /^\s*Libs\s*:(.*)$/.exec(line);
        if (m) {
            for (const tok of m[1].split(/\s+/)) {
                const lm = /^-l(.+)$/.exec(tok);
                if (lm) {
                    libs.push(lm[1]);
                }
            }
        }
    }
    return libs;
}

/** Map `-l` flag -> .pc file by reading every .pc's Libs line. Built once.
 * A .pc whose own name matches the flag wins over mere mentions
 * (e.g. -lX11 resolves to x11.pc, not glew.pc which merely links it). */
let pcByLibCache: Map<string, string> | null = null;

export function pcByLib(): Map<string, string> {
    if (pcByLibCache) {
        return pcByLibCache;
    }
    const all = pcFiles();
    const firstMention = new Map<string, string>();
    for (const pc of all) {
        let text: string;
        try {
            text = fs.readFileSync(pc, "utf8");
        } catch {
            continue;
        }
        for (const lib of parseLibsLine(text)) {
            if (!firstMention.has(lib)) {
                firstMention.set(lib, pc);
            }
        }
    }
    const map = new Map<string, string>(firstMention);
    const byName = new Map<string, string>();
    for (const pc of all) {
        byName.set(path.basename(pc, ".pc").toLowerCase(), pc);
    }
    for (const [lib] of firstMention) {
        const own = byName.get(lib.toLowerCase());
        if (own) {
            map.set(lib, own);
        }
    }
    pcByLibCache = map;
    return map;
}

function pcIncludeDirs(pcPath: string): string[] {
    const pcName = path.basename(pcPath, ".pc");
    const out = execQuiet("pkg-config", ["--cflags-only-I", pcName]);
    if (!out) {
        return [];
    }
    const dirs: string[] = [];
    for (const tok of out.split(/\s+/)) {
        const m = /^-I(.+)$/.exec(tok);
        if (m) {
            try {
                if (fs.statSync(m[1]).isDirectory()) {
                    dirs.push(fs.realpathSync(m[1]));
                }
            } catch {
                // ignore missing dirs
            }
        }
    }
    return dirs;
}

function collectWorker(
    starts: Array<{ dir: string; depth: number }>,
    maxDepth: number,
    budget: { files: number; bytes: number },
    seen: Set<string>,
    out: string[]
): void {
    const stack = [...starts];
    while (stack.length > 0 && budget.files > 0 && budget.bytes > 0) {
        const top = stack.pop();
        if (!top || seen.has(top.dir)) {
            continue;
        }
        seen.add(top.dir);
        let entries: fs.Dirent[];
        try {
            entries = fs.readdirSync(top.dir, { withFileTypes: true });
        } catch {
            continue;
        }
        for (const ent of entries) {
            const full = path.join(top.dir, ent.name);
            if (ent.isDirectory()) {
                if (top.depth < maxDepth && !ent.name.startsWith(".")) {
                    stack.push({ dir: full, depth: top.depth + 1 });
                }
            } else if (ent.isFile() && ent.name.endsWith(".h")) {
                try {
                    const st = fs.statSync(full);
                    if (st.size > 0 && st.size < 1024 * 1024) {
                        budget.files--;
                        budget.bytes -= st.size;
                        out.push(full);
                    }
                } catch {
                    // ignore
                }
            }
        }
    }
}

function collectHeaders(roots: string[], budgetFiles = 300, budgetBytes = 8 * 1024 * 1024): string[] {
    const out: string[] = [];
    collectWorker(
        roots.map((dir) => ({ dir, depth: 0 })),
        2,
        { files: budgetFiles, bytes: budgetBytes },
        new Set<string>(),
        out
    );
    return out;
}

/** Subdirectories plausibly owned by a library, e.g. X11/ for -lX11. */
function libSubdirs(roots: string[], flag: string): string[] {
    const needle = flag.toLowerCase();
    const out: string[] = [];
    for (const root of roots) {
        let entries: fs.Dirent[];
        try {
            entries = fs.readdirSync(root, { withFileTypes: true });
        } catch {
            continue;
        }
        for (const ent of entries) {
            if (ent.isDirectory() && ent.name.toLowerCase() === needle) {
                out.push(path.join(root, ent.name));
            }
        }
    }
    return out;
}

/** Top-level headers plausibly owned by a library, e.g. sqlite3.h. */
function libTopHeaders(roots: string[], flag: string): string[] {
    const needle = flag.toLowerCase();
    const out: string[] = [];
    for (const root of roots) {
        let entries: fs.Dirent[];
        try {
            entries = fs.readdirSync(root, { withFileTypes: true });
        } catch {
            continue;
        }
        for (const ent of entries) {
            if (
                ent.isFile() &&
                ent.name.endsWith(".h") &&
                path.basename(ent.name, ".h").toLowerCase().startsWith(needle)
            ) {
                out.push(path.join(root, ent.name));
            }
        }
    }
    return out;
}

const PROTO_REGEX =
    /^\s*(?:extern\s+)?(?!typedef\b|define\b|struct\b|union\b|enum\b)([\w][\w\s\*]*?)\s+(\w+)\s*\(([^;{}]*)\)\s*(?:__attribute__\s*\(\([^)]*\)\)\s*)*(?:__THROW\s*)?;\s*$/;

function stripLineComment(line: string): string {
    const idx = line.indexOf("//");
    return idx >= 0 ? line.slice(0, idx) : line;
}

/** Extract single- (and short multi-) line C prototypes from header text. */
export function extractPrototypes(headerName: string, text: string): Array<{ name: string; signature: string }> {
    const found: Array<{ name: string; signature: string }> = [];
    const lines = text.split("\n");
    let pending = "";
    let pendingLines = 0;
    const flush = (chunk: string): void => {
        const clean = chunk
            .replace(/\/\*.*?\*\//g, " ")
            .replace(/\s+/g, " ")
            .replace(/\s+,/g, ",")
            .trim();
        if (!clean) {
            return;
        }
        const m = PROTO_REGEX.exec(clean);
        if (!m) {
            return;
        }
        const name = m[2];
        if (/^[A-Z0-9_]+$/.test(name) || name.startsWith("__")) {
            return;
        }
        const signature = `${m[1].replace(/\s+/g, " ").trim()} ${name}(${m[3].replace(/\s+/g, " ").trim()})`;
        found.push({ name, signature });
    };
    for (const raw of lines) {
        const line = stripLineComment(raw);
        if (!line.trim()) {
            continue;
        }
        if (line.trim().startsWith("#")) {
            // Preprocessor directives are never part of a prototype; a
            // function-like macro must not swallow the next declaration.
            pending = "";
            pendingLines = 0;
            continue;
        }
        if (!pending && !line.includes("(")) {
            continue;
        }
        pending += (pending ? " " : "") + line.trim();
        pendingLines++;
        // Flush at the terminating `;`. The line cap is generous (Xlib uses
        // ~15-line declarations) and only bounds runaway constructs; the
        // regex itself rejects anything that is not a declaration.
        if (pending.includes(";") || pendingLines >= 40) {
            if (pending.includes(";")) {
                flush(pending.slice(0, pending.indexOf(";") + 1));
            }
            pending = "";
            pendingLines = 0;
        }
    }
    return found;
}

/** One-line description from the man page NAME section, or "". Cached.
 * Prefers section 3 (library calls), then 2 (syscalls), so `printf` gives
 * the C function instead of the shell command. */
const manCache = new Map<string, string>();

export function manSummary(name: string): string {
    const key = name.toLowerCase();
    const hit = manCache.get(key);
    if (hit !== undefined) {
        return hit;
    }
    let summary = "";
    for (const section of ["3", "2"]) {
        const where = execQuiet("man", ["-w", section, name], 8000);
        if (where) {
            const page = execQuiet("man", [section, name], 8000);
            if (page) {
                // Strip overstrike sequences (the `col -b` equivalent).
                summary = parseManName(page.replace(/.\x08/g, ""));
                if (summary) {
                    break;
                }
            }
        }
    }
    manCache.set(key, summary);
    return summary;
}

export function parseManName(page: string): string {
    // `man | col -b` loses backspaces; tests pass pre-joined text.
    const lines = page.split("\n");
    const start = lines.findIndex((l) => l.trim() === "NAME");
    if (start < 0) {
        return "";
    }
    const desc: string[] = [];
    for (let i = start + 1; i < lines.length; i++) {
        const line = lines[i];
        if (!line.trim()) {
            break;
        }
        if (!/^\s/.test(line)) {
            break;
        }
        desc.push(line.trim());
    }
    const joined = desc.join(" ");
    const dash = joined.indexOf(" - ");
    if (dash < 0) {
        return "";
    }
    return joined.slice(dash + 3).trim();
}

import { renderLibcFunction } from "./libcData";

export function renderHeaderFunction(fn: HeaderFunction, summary: string): string {
    const doc = renderLibcFunction(
        { name: fn.name, header: fn.header, signature: fn.signature, summary, returns: "" },
        `-l${fn.lib}`
    );
    return `${doc}\n\nDeclared in \`${fn.header}\`.`;
}

export interface HeaderIndex {
    functions: Map<string, HeaderFunction[]>;
    scannedLibs: string[];
}

/** Scan headers for the given `-l` flags.
 * Attribution is verified, not guessed: a prototype is kept only when the
 * flag's own library exports that symbol (`isExported`), so scanning shared
 * include trees cannot misattribute e.g. stdio functions to X11.
 * Pass 1 scans lib-named subdirs and matching top-level headers first so the
 * owning headers win the file budget; pass 2 sweeps the rest. */
export function buildHeaderIndex(
    flags: string[],
    isExported?: (flag: string, name: string) => boolean
): HeaderIndex {
    const functions = new Map<string, HeaderFunction[]>();
    const scannedLibs: string[] = [];
    const byLib = pcByLib();
    for (const flag of flags) {
        const pc = byLib.get(flag);
        if (!pc) {
            continue;
        }
        let roots = pcIncludeDirs(pc);
        if (!roots.length) {
            roots = ["/usr/include"];
        }
        scannedLibs.push(flag);
        const seen = new Set<string>();
        const headers: string[] = [];
        const budget = { files: 800, bytes: 16 * 1024 * 1024 };
        headers.push(...libTopHeaders(roots, flag));
        collectWorker(
            libSubdirs(roots, flag).map((dir) => ({ dir, depth: 0 })),
            3,
            budget,
            seen,
            headers
        );
        collectWorker(
            roots.map((dir) => ({ dir, depth: 0 })),
            2,
            budget,
            seen,
            headers
        );
        for (const header of headers) {
            let text: string;
            try {
                text = fs.readFileSync(header, "utf8");
            } catch {
                continue;
            }
            for (const proto of extractPrototypes(path.basename(header), text)) {
                if (isExported && !isExported(flag, proto.name)) {
                    continue;
                }
                const key = proto.name.toLowerCase();
                const arr = functions.get(key) || [];
                if (!arr.some((f) => f.signature === proto.signature)) {
                    arr.push({
                        name: proto.name,
                        header: path.basename(header),
                        signature: proto.signature,
                        summary: "",
                        lib: flag,
                    });
                    functions.set(key, arr);
                }
            }
        }
    }
    return { functions, scannedLibs };
}
